For adding custom directives to vnodes.
  * **Type**
ts```
function withDirectives(
  vnode: VNode,
  directives: DirectiveArguments
): VNode
// [Directive, value, argument, modifiers]
type DirectiveArguments = Array<
  | [Directive]
  | [Directive, any]
  | [Directive, any, string]
