    @enter="onEnter"
    @leave="onLeave">
slot></slot> <!-- pass down slot content -->
  </Transition>
</template>
<style>
/*
  Necessary CSS...
  Note: avoid using <style scoped> here since it
  does not apply to slot content.
*/
</style>
```

