js```
const x = ref(0)
const y = ref(0)
// single ref
watch(x, (newX) => {
  console.log(`x is ${newX}`)
})
// getter
watch(
  () => x.value + y.value,
  (sum) => {
    console.log(`sum of x + y is: ${sum}`)


